import {readFeedingBoard,feedingCaseView,createFeedingBoard,setSortDraft,setIdeaDraft,checkSort,checkIdea,noteFeedingSupport,noteFeedingTeaching,feedingSupportFlags} from './feeding-board-core.mjs';
import {feedingBoardCopy as copy} from './feeding-board-content.mjs';
import {feedingBoardArt} from './feeding-board-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=x=>{try{return JSON.stringify(x,null,2);}catch{return 'Original data cannot be displayed here.';}};
const btn=(text,attrs='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(text)}</button>`;
let visits=new WeakMap();
export function resetFeedingBoardView(state){if(state&&typeof state==='object')visits.delete(state);else visits=new WeakMap();}
function visit(state,explorerId=''){let u=visits.get(state);if(!u||u.explorerId!==explorerId){const v=readFeedingBoard(state);u={explorerId,tab:'sort',id:v.status==='ready'?(v.source.animals.find(a=>{const c=feedingCaseView(v,a.id);return c.recordReadable&&!c.record;})||v.source.animals[0]).id:null,helper:null,step:0};visits.set(state,u);}return u;}
const choiceText=(v,c,id)=>c.kind==='sort'?v.source.baskets.find(b=>b.id===id)?.label:c.case.options.find(o=>o.id===id)?.text;
const picked=c=>c.draft?.[c.kind==='sort'?'basketId':'choiceId'];
const checked=c=>c.latest?.[c.kind==='sort'?'basketId':'choiceId'];
const draftLabel=c=>c.draftStatus==='unreadable'?copy.unreadableCase:c.draftStatus==='changed'?'Changed since check':c.draftStatus==='checked'?'Checked here':c.draftStatus==='waiting'?'Waiting · earlier check recorded':'Not checked yet';
function animal(a,{compact=false}={}){return `<section class="fb-evidence${compact?' fb-compact-evidence':''}"><div class="fb-animal-picture">${feedingBoardArt(a)}</div><h3>${esc(a.name)}</h3><div class="fb-food-plate"><strong>Food examples</strong><div class="fb-foods">${a.foods.map(f=>`<figure>${feedingBoardArt(f,{food:true})}<figcaption>${esc(f.label)}</figcaption></figure>`).join('')}</div></div><p class="fb-usual-diet">${esc(a.usualDiet)}</p></section>`;}
function sourceCard(a){return `<section>${animal(a)}<p><i>${esc(a.scientificName)}</i></p><p>${esc(a.sourceNote)}</p><p>These are supplied species facts, not an observation made in this game.</p><p><a href="${esc(a.reference.url)}" target="_blank" rel="noopener noreferrer">Grown-up source: ${esc(a.reference.title)} · ${esc(a.reference.publisher)}</a></p><p>${esc(copy.artCredit)}</p></section>`;}
function feedback(v,c){if(!c.latest)return '';const id=checked(c),f=c.kind==='sort'?c.case.feedback.find(f=>f.code===c.latest.feedbackCode):c.case.options.find(f=>f.code===c.latest.feedbackCode);return `<section class="fb-feedback"><h3 id="fb-feedback" tabindex="-1">${c.kind==='sort'?'Your basket and the food clue':'Your idea and the food clues'}</h3><p>You chose: ${esc(choiceText(v,c,id))}</p><p><strong>${c.latest.outcome==='fits'?'Fits this food clue':'Look again at the food clue'}</strong></p>${f?`<p>Supplied feedback: ${esc(f.text||f.feedback)}</p>`:`<p>The original feedback code is retained: ${esc(c.latest.feedbackCode)}</p>`}${c.latest.outcome==='other'?`<p>${c.kind==='sort'?'Your animal stays where you put it. You can choose another basket and check again.':'You can choose another idea and check again.'}</p>`:''}<p>${c.record.checkCount===1?'First check here':'Checked before here'} · ${c.record.checkCount} ${c.record.checkCount===1?'check':'checks'}</p></section>`;}
const participation=(section,total,kind)=>section.status==='ready'&&!section.unreadable.length?`${section.readable.length} of ${total} ${kind} checked`:copy.unreadableCase;
function rail(v,u){return `<details class="fb-rail" open><summary>Your basket board · ${esc(participation(v.sorts,v.source.animals.length,'animals'))}</summary><div class="fb-rail-groups">${[...v.source.baskets,{id:null,label:'Waiting'}].map(b=>`<section class="fb-rail-group"><h3>${esc(b.label)}</h3>${v.source.animals.filter(a=>(feedingCaseView(v,a.id).draft?.basketId??null)===b.id).map(a=>{const c=feedingCaseView(v,a.id);return `<button type="button" class="fb-animal-button" data-fb-case="${esc(a.id)}" aria-current="${u.id===a.id?'true':'false'}">${feedingBoardArt(a,{small:true})}<strong>${esc(a.name)}</strong><span>${esc(draftLabel(c))}</span></button>`;}).join('')}${v.source.animals.filter(a=>{const c=feedingCaseView(v,a.id);return c.latest?.basketId===b.id&&c.draft?.basketId!==b.id;}).map(a=>`<p class="fb-earlier-marker">Earlier check: ${esc(a.name)}</p>`).join('')}</section>`).join('')}</div></details>`;}
const helperAvailable=(v,type)=>type==='teaching'?!!v.helpers.teaching:type==='example'?!!v.helpers.workedExample:type==='glossary'?!!v.helpers.glossary:['clue','source','bridge'].includes(type);
function controls(v,c){return `<div class="fb-toolbar" role="group" aria-label="Optional help">${[['teaching','Try the idea'],['clue','Clue'],['example','Another example'],['source','Source'],['glossary','Word help']].filter(([id])=>helperAvailable(v,id)).map(([id,label])=>btn(label,`data-fb-helper="${id}"`)).join('')}${hearButton([c.case.name||c.case.title,c.case.prompt||'',...(c.kind==='sort'?[c.case.foods.map(f=>f.label).join(', '),c.case.usualDiet]:c.case.options.map(o=>o.text))].join('. '),'Hear')}${btn('Working together',`data-fb-together aria-pressed="${c.support?.together===true}"`)}<p>${esc(copy['together explanation']||'Choose Working together if a grown-up is helping with this case. This is a report from you, not a test.')}</p>${['teaching','example','glossary'].some(type=>!helperAvailable(v,type))?`<p>${esc(copy.missingHelper)}</p>`:''}</div>`;}
function helper(v,u,c){if(!u.helper)return '';let content='',title='';const back=btn(c.kind==='sort'?'Back to my animal':'Back to my idea','data-fb-close');
 if(u.helper==='clue'){title='Clue';content=`<p>${esc(c.case.hint)}</p>`;}
 if(u.helper==='source'){title='About this food clue';content=(c.kind==='sort'?[c.case]:c.case.animalIds.map(id=>v.source.animals.find(a=>a.id===id))).map(sourceCard).join('');}
 if(u.helper==='glossary'){title='Word help';content=v.helpers.glossary?`<dl>${v.helpers.glossary.map(g=>`<dt>${esc(g.term)}</dt><dd>${esc(g.text)}</dd>`).join('')}</dl>`:`<p>${esc(copy.missingHelper)}</p>`;}
 if(u.helper==='example'){title='Try a fox example';const h=v.helpers.workedExample,a=h&&v.source.animals.find(a=>a.id===h.animalId);content=h?`${animal(a)}<div class="fb-worked-placement">${feedingBoardArt(a,{small:true})}<strong>${esc(v.source.baskets.find(b=>b.id===a.basketId)?.label)}</strong></div>${h.steps.map(t=>`<p>${esc(t)}</p>`).join('')}`:`<p>${esc(copy.missingHelper)}</p>`;}
 if(u.helper==='teaching'){title='Food decides the group';const steps=v.helpers.teaching,h=steps?.[u.step];content=h?`${h.animalIds.map(id=>{const a=v.source.animals.find(a=>a.id===id);return `${animal(a)}<div class="fb-worked-placement">${feedingBoardArt(a,{small:true})}<strong>${esc(v.source.baskets.find(b=>b.id===a.basketId)?.label)}</strong></div>`;}).join('')}<p>${esc(h.text)}</p><nav>${btn('Previous step',`data-fb-step="-1" ${u.step===0?'disabled':''}`)}${btn('Next step',`data-fb-step="1" ${u.step===steps.length-1?'disabled':''}`)}</nav><p>These are worked examples. You can return to your own choice at any step.</p>`:`<p>${esc(copy.missingHelper)}</p>`;}
 if(u.helper==='bridge'){title='One food clue, another question';const a=v.source.animals.find(a=>a.id==='ladybird'),cv=a&&feedingCaseView(v,a.id);content=a&&cv.supportReadable?`${animal(a)}<p>${esc(a.art.description)}</p><p>${esc(copy.bridgeText)}</p>`:`<p>${esc(a?copy.unreadableCase:copy.missingBridge)}</p>`;content+='<a href="#living/food">Visit Food Links</a> <a href="#living/who-eats" data-fb-return>Return to this board</a>';}
 return `<section class="fb-helper"><h2 id="fb-helper-focus" tabindex="-1">${esc(title)}</h2>${content}${back}</section>`;
}
function task(v,u){const c=feedingCaseView(v,u.id);if(!c.case)return `<p>${esc(copy.unreadableCase)}</p>`;const idea=c.kind==='idea',list=idea?v.source.contrasts:v.source.animals,index=list.findIndex(a=>a.id===u.id),id=picked(c),last=checked(c);
 return `<h2 id="fb-focus" tabindex="-1">${esc(idea?c.case.title:c.case.name)}</h2><p class="fb-instruction">${esc(!c.recordReadable||!c.draftReadable?copy.unreadableCase:idea?'Two animals, two food clues. Choose the idea that uses the foods.':copy.instruction)}</p><div class="fb-stage">${idea?`<div class="fb-pair">${c.case.animalIds.map(id=>animal(v.source.animals.find(a=>a.id===id),{compact:true})).join('')}</div>`:animal(c.case)}<section class="fb-choice-panel">${!idea&&c.case.guided.length?`<div class="fb-guided"><strong>Guided example</strong>${c.case.guided.map(t=>`<p>${esc(t)}</p>`).join('')}</div>`:''}${c.status!=='ready'?`<p>${esc(copy.unreadableCase)}</p>`:''}<fieldset class="${idea?'fb-ideas':'fb-baskets'}" ${c.status!=='ready'?'disabled':''}><legend>${esc(idea?c.case.prompt:'Choose a basket')}</legend>${(idea?c.case.options:v.source.baskets).map(o=>`<label class="${idea?'fb-idea':'fb-basket'}"><input type="radio" name="fb-choice" data-fb-choice="${esc(o.id)}" value="${esc(o.id)}" ${id===o.id?'checked':''}><strong>${esc(idea?o.text:o.label)}</strong>${!idea&&id===o.id?`<span class="fb-trying">${feedingBoardArt(c.case,{small:true})}<span>${esc(!c.recordReadable?copy.unreadableCase:last===id?'Checked here':'Trying here · not checked')}</span></span>`:''}${!idea&&last===o.id&&id!==o.id?'<span class="fb-checked">Checked here · earlier check</span>':''}</label>`).join('')}</fieldset>${btn(idea?'Check this idea':'Check this basket',`data-fb-check ${!id||c.status!=='ready'?'disabled':''}`,true)}<p class="fb-choice-state">${!c.recordReadable||!c.draftReadable?esc(copy.unreadableCase):!id?(c.latest?'Waiting · earlier check recorded':idea?'Choose an idea before checking.':'Choose a basket before checking.'):esc(draftLabel(c))}</p>${!idea&&last?`<p>Your checked basket: ${esc(choiceText(v,c,last))}.</p>`:''}${c.recordReadable&&c.draftReadable&&!c.latest&&!idea?'<p>Moving an animal keeps your arrangement. Check records an answer. You can move it again.</p>':''}${feedback(v,c)}</section></div><p class="fb-qualifier">${esc(v.source.notice)} ${esc(copy.scale)}</p><nav class="fb-navigation" aria-label="${idea?'Idea':'Animal'} navigation">${btn(idea?'Previous idea':'Previous animal',`data-fb-next="-1" ${index===0?'disabled':''}`)}${btn(idea?'Next idea':'Next animal',`data-fb-next="1" ${index===list.length-1?'disabled':''}`)}${btn('Skip for now',`data-fb-next="1" ${index===list.length-1?'disabled':''}`)}</nav>${!idea?`<div class="fb-reason"><p>${esc(copy.reason)}</p><p>${esc(copy.reasonNote)}</p><p>For an omnivore, invite a plant food and an animal food.</p></div>`:''}${controls(v,c)}${helper(v,u,c)}${idea?`<p class="fb-ideas-participation">${esc(participation(v.ideas,v.source.contrasts.length,'ideas'))}</p><nav class="fb-idea-rail" aria-label="Choose an idea">${v.source.contrasts.map(x=>btn(x.title,`data-fb-case="${esc(x.id)}" aria-current="${x.id===u.id?'true':'false'}"`)).join('')}</nav>`:rail(v,u)}`;
}
export function feedingBoardEntry(){return `<aside class="fb-entry"><a href="#living/who-eats">The Feeding Board</a><p>Who eats plants, animals or both? Make a board from the supplied food clues.</p></aside>`;}
function pageHeader(){return `<header class="fb-heading"><a href="#living">← Living Garden</a><h1>The Feeding Board</h1><span>Supplied science examples</span></header>`;}
export function feedingBoardPage(state,explorerId=''){const v=readFeedingBoard(state),u=visit(state,explorerId);let content;
 if(v.status==='missing')content=`<h2 id="fb-focus" tabindex="-1">Who eats what?</h2><p>${esc(copy.invitation)}</p><p>${esc(copy.boundary)}</p><p>${esc(copy.beforeStart)}</p>${btn('Start a board','data-fb-start',true)}`;
 else if(v.status!=='ready')content=`<h2 id="fb-focus" tabindex="-1">Earlier work is retained</h2><p>${esc(v.status==='unsupported'?copy.unsupported:copy.unreadable)}</p><a href="#notes">Grown-up notes</a>`;
 else {if(![...v.source.animals,...v.source.contrasts].some(c=>c.id===u.id)){u.tab='sort';u.id=v.source.animals[0].id;u.helper=null;}content=`<nav class="fb-tabs" aria-label="Feeding Board pages">${btn('Animal baskets',`data-fb-tab="sort" aria-current="${u.tab==='sort'?'page':'false'}"`)}${v.source.contrasts.length?btn('Looks and food',`data-fb-tab="idea" aria-current="${u.tab==='idea'?'page':'false'}"`):''}</nav>${task(v,u)}${btn('Take this food clue to Food Links','data-fb-helper="bridge"')}<details class="fb-grownup"><summary>Grown-up guide</summary>${(copy.grownup||[]).map(t=>`<p>${esc(t)}</p>`).join('')}<p>${esc(copy.basketKey)}</p><p>The game's confirmed reset removes this explorer's board records from this device. It does not remove another explorer's work or files you already downloaded.</p></details>`;}
 return `<section data-feeding-board-view>${pageHeader()}<p id="fb-status" class="fb-status" role="status" aria-live="polite" tabindex="-1"></p>${content}<p>${btn('Download our notes','data-fb-download')} <a href="#notes">Grown-up notes</a></p></section>`;
}
function observation(v,c,check,label){const id=check[c.kind==='sort'?'basketId':'choiceId'],f=(c.kind==='sort'?c.case.feedback:c.case.options).find(f=>f.code===check.feedbackCode);return `<section><h4>${label}</h4><p>You chose: ${esc(choiceText(v,c,id))}</p><p>Recorded outcome: ${esc(check.outcome)}. Feedback code: ${esc(check.feedbackCode)}.</p>${f?`<p>Supplied feedback: ${esc(f.text||f.feedback)}</p>`:''}<ul>${feedingSupportFlags.map((key,i)=>`<li>${['Clue or word help opened','Worked example opened','Source note opened','Hear requested','Working together reported'][i]}: ${check.supportBefore[key]?'Recorded before this check':'Not recorded before this check'}</li>`).join('')}<li>Teaching example opened: ${check.teachingBefore?'Recorded before this check':'Not recorded before this check'}</li><li>Feedback available for this check: ${check.afterFeedback?'yes':'no'}</li></ul></section>`;}
export function feedingBoardNotes(state){const v=readFeedingBoard(state);if(v.status==='missing')return '';return `<details class="panel fb-notes"><summary>The Feeding Board</summary><p>Supplied names and food evidence; fitting responses do not establish independent mastery. Saved drafts are ungraded arrangements. First check and latest retry are retained; intermediate retries are not.</p>${v.status==='ready'?`<h3>${esc(v.source.title)}</h3><p>${esc(v.source.origin)}</p><p>${esc(v.source.notice)}</p>${[...v.source.animals,...v.source.contrasts].map(a=>{const c=feedingCaseView(v,a.id);return `<section><h3>${esc(a.name||a.title)}</h3>${c.kind==='sort'?`<p>${esc(a.scientificName)} · ${esc(a.foods.map(f=>f.label).join(' · '))}</p><p>${esc(a.usualDiet)}</p>`:''}<p>Saved ungraded ${c.kind==='sort'?'basket':'idea'}: ${esc(!c.draftReadable?copy.unreadableCase:c.draft?choiceText(v,c,picked(c)):'Waiting')}. ${esc(draftLabel(c))}.</p><p>Latest checked ${c.kind==='sort'?'basket':'idea'}: ${esc(!c.recordReadable?copy.unreadableCase:c.latest?choiceText(v,c,checked(c)):'No check recorded')}.</p>${c.record?`<p>${c.record.checkCount} ${c.record.checkCount===1?'check':'checks'} · ${c.record.checkCount===1?'First check here':'Checked before here'}</p>${observation(v,c,c.record.first,'First check')}${c.record.latest?observation(v,c,c.record.latest,'Latest retry'):''}`:c.recordReadable?'<p>No check recorded</p>':`<p>${esc(copy.unreadableCase)}</p>`}${c.status!=='ready'?`<p>${esc(copy.unreadableCase)}</p>`:''}</section>`;}).join('')}`:`<p>${esc(v.status==='unsupported'?copy.unsupported:copy.unreadable)}</p>`}<details><summary>Original saved Feeding Board data</summary><pre>${esc(json(state.feedingBoard))}</pre></details></details>`;}
export function bindFeedingBoard(state,{notebook=()=>state,explorerId=()=>'',isActive=()=>true,save,render,focus,canExport,download,stopSpeech,stopSound}={}){
 const host=document.querySelector('[data-feeding-board-view]');if(!host)return;const u=visit(state,explorerId()),boundExplorer=explorerId(),boundTab=u.tab,boundCase=u.id,boundSource=json(readFeedingBoard(state).source);
 const live=el=>el.isConnected&&host.isConnected&&notebook()===state&&explorerId()===boundExplorer&&isActive()&&visits.get(state)===u&&u.tab===boundTab&&u.id===boundCase&&json(readFeedingBoard(state).source)===boundSource;
 const status=(text,takeFocus=false)=>{const box=host.querySelector('#fb-status');if(box){box.textContent=text;if(takeFocus)box.focus();}};
 const refusal=r=>r.code==='check-count-cap'?copy.countCap:r.code==='report-safety'?copy.reportRefusal:copy.unreadableCase;
 const persist=()=>{try{const r=save?.();return r?.enabled===false?copy.saveOff:r?.ok===false?copy.saveFailure:'';}catch{return copy.saveFailure;}};
 const redraw=(target='#fb-focus',message='',write=false)=>{const note=write?persist():'';stopSpeech?.();stopSound?.();render?.();const next=document.querySelector('[data-feeding-board-view]');if(!next)return;const box=next.querySelector('#fb-status');if(box)box.textContent=[message,note].filter(Boolean).join(' ');if(focus)focus(target);else next.querySelector(target)?.focus();};
 const bind=(selector,fn)=>host.querySelectorAll(selector).forEach(el=>el.addEventListener('click',event=>{if(!live(el)){event.preventDefault();event.stopImmediatePropagation();return;}fn(el,event);}));
 bind('[data-fb-start]',()=>{const r=createFeedingBoard(state,canExport);if(!r.ok)return status(refusal(r),true);const v=readFeedingBoard(state);u.id=v.source.animals[0].id;redraw('#fb-focus','',r.changed);});
 bind('[data-fb-download]',()=>download?.());
 bind('[data-fb-tab]',b=>{u.tab=b.dataset.fbTab;const v=readFeedingBoard(state);u.id=(u.tab==='sort'?v.source.animals:v.source.contrasts)[0]?.id;u.helper=null;redraw();});
 bind('[data-fb-case]',b=>{u.id=b.dataset.fbCase;u.helper=null;redraw();});
 bind('[data-fb-next]',b=>{const v=readFeedingBoard(state),list=u.tab==='sort'?v.source.animals:v.source.contrasts,index=list.findIndex(c=>c.id===u.id),next=list[index+Number(b.dataset.fbNext)];if(next){u.id=next.id;u.helper=null;redraw();}});
 host.querySelectorAll('[data-fb-choice]').forEach(el=>el.addEventListener('change',event=>{if(!live(el)){event.stopImmediatePropagation();return;}const c=feedingCaseView(state,u.id),r=(c.kind==='sort'?setSortDraft:setIdeaDraft)(state,u.id,el.dataset.fbChoice,canExport);if(!r.ok){el.checked=false;const actual=picked(feedingCaseView(state,u.id));host.querySelectorAll('[data-fb-choice]').forEach(e=>e.checked=e.dataset.fbChoice===actual);return status(refusal(r),true);}if(r.changed)redraw(`[data-fb-choice="${CSS.escape(el.dataset.fbChoice)}"]`,c.kind==='sort'?`Trying ${c.case.name} in ${choiceText(readFeedingBoard(state),c,el.dataset.fbChoice)}. This has not been checked.`:'Idea choice kept as an ungraded draft.',true);}));
 bind('[data-fb-check]',()=>{const c=feedingCaseView(state,u.id),r=(c.kind==='sort'?checkSort:checkIdea)(state,u.id,canExport);if(!r.ok)return status(refusal(r),true);if(r.changed)redraw('#fb-feedback','',true);else host.querySelector('#fb-feedback')?.focus();});
 bind('[data-fb-together]',()=>{const r=noteFeedingSupport(state,u.id,'together',canExport);if(!r.ok)return status(refusal(r),true);if(r.changed)redraw('[data-fb-together]','Working together reported.',true);});
 bind('[data-fb-helper]',b=>{const type=b.dataset.fbHelper,v=readFeedingBoard(state);if(v.status!=='ready'||!helperAvailable(v,type))return status(copy.missingHelper,true);let r;
 if(type==='bridge'){const a=v.source.animals.find(a=>a.id==='ladybird');if(a){const c=feedingCaseView(v,a.id);if(!c.supportReadable){u.helper=type;redraw('#fb-helper-focus');return;}r=noteFeedingSupport(state,a.id,'source',canExport);}else r={ok:true,changed:false};}
 else r=type==='teaching'?noteFeedingTeaching(state,canExport):noteFeedingSupport(state,u.id,{glossary:'clue',clue:'clue',source:'source',example:'example'}[type],canExport);
 if(!r.ok)return status(refusal(r),true);u.helper=type;u.step=0;redraw('#fb-helper-focus','',r.changed);});
 bind('[data-fb-close]',()=>{const type=u.helper;u.helper=null;redraw(`[data-fb-helper="${type}"]`);});
 bind('[data-fb-return]',(b,e)=>{e.preventDefault();u.helper=null;redraw();});
 bind('[data-fb-step]',b=>{const v=readFeedingBoard(state);u.step=Math.max(0,Math.min((v.helpers.teaching?.length||1)-1,u.step+Number(b.dataset.fbStep)));redraw('#fb-helper-focus');});
 host.querySelectorAll('[data-speak]').forEach(el=>el.addEventListener('click',event=>{if(!live(el)){event.preventDefault();event.stopImmediatePropagation();return;}const r=noteFeedingSupport(state,u.id,'narration',canExport);if(!r.ok){event.preventDefault();event.stopImmediatePropagation();status(refusal(r),true);return;}if(r.changed){const note=persist();if(note)status(note);}},true));
}
